 names=('STABILITY_RANKING','ANNUAL_COMPARISON','MONTHLY_COMPARISON','PORTFOLIO_SUBSETS','INSTRUMENT_COMPARISON','FILTER_CONTRIBUTION','BUILD_REGISTRY')
 tables={n:read_csv(out/(n+'.csv')) for n in names};ranks=tables['STABILITY_RANKING'];causal=[r for r in ranks if r['mode']=='NEXT_OPEN'];ideal=[r for r in ranks if r['mode']=='SIGNAL_CLOSE']
 pf=max(causal,key=lambda r:float(r['gross_PF']));profit=max(causal,key=lambda r:float(r['gross_R']));stable=causal[0]
